// Прод: только GET через API request, без браузера и JS.
import { test, expect } from '@playwright/test';

function decodeEntities(s: string): string {
  return s
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

function parseAttrs(tag: string): Record<string, string> {
  const attrs: Record<string, string> = {};
  const re = /([^\s"'<>\/=]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(tag))) {
    attrs[m[1].toLowerCase()] = decodeEntities(m[2] ?? m[3] ?? m[4] ?? '');
  }
  return attrs;
}

function metaValues(html: string, key: string): string[] {
  const out: string[] = [];
  for (const tag of html.match(/<meta\b[^>]*>/gi) ?? []) {
    const a = parseAttrs(tag);
    if ((a['property'] === key || a['name'] === key) && 'content' in a) out.push(a['content']);
  }
  return out;
}

function canonicals(html: string): string[] {
  const out: string[] = [];
  for (const tag of html.match(/<link\b[^>]*>/gi) ?? []) {
    const a = parseAttrs(tag);
    if (a['rel']?.toLowerCase().split(/\s+/).includes('canonical') && a['href'] !== undefined) out.push(a['href']);
  }
  return out;
}

test.describe('SEO техническая инфраструктура — og/twitter', () => {
  test('faq.html: og:* и twitter:* в сыром HTML, og:image отвечает 200 image/jpeg #9f2c12 @desktop @prod-safe', async ({ request }) => {
    // 1. GET /faq.html без браузера
    const res = await request.get('/faq.html');
    expect(res.status()).toBe(200);
    expect(res.headers()['content-type']).toContain('text/html');
    const html = await res.text();

    // 2. Извлечь canonical, og:* и twitter:*
    const canon = canonicals(html);
    const og: Record<string, string[]> = {};
    for (const k of ['og:title', 'og:description', 'og:url', 'og:image']) og[k] = metaValues(html, k);
    const tw: Record<string, string[]> = {};
    for (const k of ['twitter:card', 'twitter:title', 'twitter:description', 'twitter:image']) tw[k] = metaValues(html, k);

    for (const k of Object.keys(og)) {
      expect(og[k], `${k} ровно один`).toHaveLength(1);
      expect(og[k][0].trim(), `${k} не пуст`).not.toBe('');
    }
    expect(og['og:title'][0]).toContain('שאלות ותשובות');

    expect(canon, 'единственный canonical').toHaveLength(1);
    expect(og['og:url'][0]).toBe('https://www.biz4sale.co.il/faq.html');
    expect(og['og:url'][0]).toBe(canon[0]);

    expect(tw['twitter:card'], 'twitter:card один').toHaveLength(1);
    expect(tw['twitter:card'][0]).toBe('summary_large_image');
    for (const k of ['twitter:title', 'twitter:description', 'twitter:image']) {
      expect(tw[k].length, `${k} присутствует`).toBeGreaterThanOrEqual(1);
      expect(tw[k][0].trim(), `${k} не пуст`).not.toBe('');
    }

    const ogImage = og['og:image'][0].trim();
    const twImage = tw['twitter:image'][0].trim();
    expect(ogImage).toMatch(/^https:\/\//);
    expect(twImage).toMatch(/^https:\/\//);

    // 3. GET og:image и (если отличается) twitter:image
    const ogRes = await request.get(ogImage);
    expect(ogRes.status()).toBe(200);
    expect(ogRes.headers()['content-type']).toContain('image/jpeg');
    expect((await ogRes.body()).length).toBeGreaterThan(0);

    if (twImage !== ogImage) {
      const twRes = await request.get(twImage);
      expect(twRes.status()).toBe(200);
      expect(twRes.headers()['content-type']).toMatch(/^image\//);
    }
  });
});
